f;f=e;e=(d+t1)%4294967296 d=c;c=b;b=a;a=(t1+t2)%4294967296 end H[1]=(H[1]+a)%4294967296;H[2]=(H[2]+b)%4294967296 H[3]=(H[3]+c)%4294967296;H[4]=(H[4]+d)%4294967296 H[5]=(H[5]+e)%4294967296;H[6]=(H[6]+f)%4294967296 H[7]=(H[7]+g)%4294967296;H[8]=(H[8]+h)%4294967296 end local out={}for i=1,8 do out[i]=string.format("%08x",H[i])end return table.concat(out)end local function hexToBytes(hex)local s=""for i=1,#hex,2 do s=s..string.char(tonumber(hex:sub(i,i+1),16))end return s end local function hmacSha256Bin(key,msg)local blockSize=64 if #key>blockSize then key=hexToBytes(sha256(key))end key=key..string.rep("\0",blockSize-#key)local iKey,oKey={},{}for i=1,blockSize do local b=key:byte(i)iKey[i]=string.char(bxor(b,0x36))oKey[i]=string.char(bxor(b,0x5c))end iKey=table.concat(iKey)oKey=table.concat(oKey)local innerHash=hexToBytes(sha256(iKey..msg))return hexToBytes(sha256(oKey..innerHash))end local function hmacSha256Hex(key,msg)local blockSize=64 if #key>blockSize then key=hexToBytes(sha256(key))end key=key..string.rep("\0",blockSize-#key)local iKey,oKey={},{}for i=1,blockSize do local b=key:byte(i)iKey[i]=string.char(bxor(b,0x36))oKey[i]=string.char(bxor(b,0x5c))end iKey=table.concat(iKey)oKey=table.concat(oKey)local innerHash=hexToBytes(sha256(iKey..msg))return sha256(oKey..innerHash)end return{hash=sha256,hmac=hmacSha256Bin,hmacHex=hmacSha256Hex,hexToBytes=hexToBytes,}
